A candidate writes this `filter` polyfill. What does the last line log?

```js
Array.prototype.myFilter = function (callback) {
  const result = [];
  for (let i = 0; i < this.length; i++) {
    if (callback(this[i], i, this)) result[i] = this[i];
  }
  return result;
};

const evens = [1, 2, 3, 4].myFilter((n) => n % 2 === 0);
console.log(evens.length);
```

