A candidate's hand-written promise passes simple tests. What does this log, and how does it differ from a native promise?

```js
class MyPromise {
  constructor(executor) {
    this.state = 'pending';
    this.handlers = [];
    const resolve = (value) => {
      if (this.state !== 'pending') return;
      this.state = 'fulfilled';
      this.value = value;
      this.handlers.forEach((h) => h(value));
    };
    executor(resolve);
  }
  then(onFulfilled) {
    if (this.state === 'fulfilled') onFulfilled(this.value);
    else this.handlers.push(onFulfilled);
  }
}

const p = new MyPromise((resolve) => resolve(1));
p.then((v) => console.log('then', v));
console.log('sync');
```

