Here is a candidate's `Promise.any` polyfill. `delay(ms, value)` fulfils with `value` after `ms`. What happens with `any([delay(50, 'ok'), Promise.reject(new Error('fail'))])`?

```js
function any(promises) {
  return new Promise((resolve, reject) => {
    const errors = [];
    promises.forEach((p, i) => {
      Promise.resolve(p).then(resolve, (err) => {
        errors[i] = err;
        if (errors.length === promises.length) {
          reject(new AggregateError(errors, 'All promises were rejected'));
        }
      });
    });
  });
}
```

This top-level-await module caches users by id. What does it log?

```js
let calls = 0;
const fetchUser = (id) => {
  calls++;
  return new Promise((resolve) => setTimeout(() => resolve({ id }), 50));
};

const cache = new Map();
async function getUser(id) {
  if (cache.has(id)) return cache.get(id);
  const user = await fetchUser(id);
  cache.set(id, user);
  return user;
}

await Promise.all([getUser(1), getUser(1), getUser(1)]);
await getUser(1);
console.log(calls);
```

A network blip makes the first `cachedFetch('/api/rates')` reject. For the next minute, every call for that key fails at once without touching the network. Which change fixes this and still shares in-flight requests?

```js
const cache = new Map();
function cachedFetch(key, ttl = 60_000) {
  const hit = cache.get(key);
  if (hit && Date.now() - hit.time < ttl) return hit.promise;
  const promise = fetchJSON(key);
  cache.set(key, { promise, time: Date.now() });
  return promise;
}
```

